package com.ruoyi.medical.persistence;
import com.ruoyi.medical.contracts.SchemaCatalogue;import com.ruoyi.medical.identity.*;import com.ruoyi.medical.persistence.mapper.*;import org.springframework.context.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnExpression;import org.springframework.beans.factory.annotation.Value;
@Configuration @ConditionalOnExpression("${medical.model-runtime.enabled:false} and ${medical.formal-invocation.enabled:false}")
public class ModelRuntimeConfiguration {
 @Bean ApprovedCredentialAuthority approvedCredentialAuthority(@Value("${medical.model-runtime.approved-credential-reference-file}") String file){return new ApprovedCredentialAuthority(new ConfiguredCredentialDirectory(java.nio.file.Path.of(file)));}
 @Bean RuntimeGovernanceSchema runtimeGovernanceSchema()throws Exception{return new RuntimeGovernanceSchema();}
 @Bean ConnectionVerificationSchema connectionVerificationSchema()throws Exception{return new ConnectionVerificationSchema();}
 @Bean ConnectionVerificationService connectionVerificationService(EnterpriseAccess access,ConnectionVerificationMapper mapper,PermissionMapper permissions,ResourceReadAuthority resources,ModelConfigurationService models,ApprovedCredentialAuthority credentials,FormalInvocationService invocations,ConnectionVerificationSchema schema,PermissionSchema json,IdentityDirectoryPolicy policy,@Value("${medical.model-runtime.maximum-connection-age-seconds}") long age){return new ConnectionVerificationService(access,mapper,permissions,resources,models,credentials,invocations,schema,json,policy,age);}
 @Bean ModelPolicyBasisAuthority modelPolicyBasisAuthority(SourceReadAuthority sources,DocumentUploadPolicy policy){policy.requireConfigured();return new ModelPolicyBasisAuthority(sources,policy.environment(),policy.region());}
 @Bean ModelEligibilityAuthority modelEligibilityAuthority(ModelConfigurationService models,ModelEligibilityMapper mapper,ConnectionVerificationService connections,ApprovedCredentialAuthority credentials,ResourceReadAuthority resources,PermissionMapper permissions,PermissionAuthority grants,RuntimeGovernanceSchema schema,PermissionSchema json,ModelPolicyBasisAuthority policyBasis,PlatformMemberIdentityStatus identities)throws Exception{return new ModelEligibilityAuthority(models,mapper,connections,credentials,resources,permissions,grants,schema,json,SchemaCatalogue.fromClasspath(),policyBasis,identities);}
 @Bean ModelEligibilityService modelEligibilityService(EnterpriseAccess access,ModelConfigurationService models,ModelEligibilityMapper mapper,ConnectionVerificationService connections,ModelPolicyBasisAuthority policyBasis,ResourceReadAuthority resources,PermissionMapper permissions,ModelEligibilityAuthority authority,RuntimeGovernanceSchema schema,PermissionSchema json,IdentityDirectoryPolicy policy){return new ModelEligibilityService(access,models,mapper,connections,policyBasis,resources,permissions,authority,schema,json,policy);}
}
